import React from 'react';
import { Carousel } from 'antd';
import './CarouselComponent.css';
import banner1 from '../images/education/banner1_2d@2x.png';
import banner2 from '../images/education/banner2_2d@2x.png' ;
import banner3 from '../images/education/LeaderTopIQ.png' ;

const CarouselComponent = ({ onLoginClick }) => {
    return (
        <Carousel autoplay className="carousel-container">
            <div className="carousel-slide">
                <div className="carousel-content">
                    <div className="carousel-text-content">
                        <h2 className="carousel-title">Добро пожаловать</h2>
                        <p className="carousel-text">Начните обучение на нашей платформе цифровых учебников!</p>
                        <button className="carousel-button" onClick={onLoginClick}>Начать</button>
                    </div>
                    <img
                        className="carousel-image"
                        src={banner1}
                        alt="Добро пожаловать"
                    />
                </div>
            </div>
            <div className="carousel-slide">
                <div className="carousel-content">
                    <div className="carousel-text-content">
                        <h2 className="carousel-title">Учимся вместе</h2>
                        <p className="carousel-text">Мы учимся вместе, мы стремимся к развитию интеллекта!</p>
                        <button className="carousel-button" onClick={onLoginClick}>Начать</button>
                    </div>
                    <img
                        className="carousel-image"
                        src={banner2}
                        alt="Учимся вместе"
                    />
                </div>
            </div>
            <div className="carousel-slide">
                <div className="carousel-content">
                    <div className="carousel-text-content">
                        <h2 className="carousel-title">Третья страница</h2>
                        <p className="carousel-text">Описание третьей страницы карусели.</p>
                        <button className="carousel-button" onClick={onLoginClick}>Начать</button>
                    </div>
                    <img
                        className="carousel-image"
                        src={banner3}
                        alt="Третья страница"
                    />
                </div>
            </div>
        </Carousel>
    );
};

export default CarouselComponent;
