import React from 'react';
import { Carousel } from 'antd';
import './Testimonials.css';
import { LeftOutlined, RightOutlined } from '@ant-design/icons';

// Testimonials data
const testimonials = [
    {
        text: 'Электронные учебники помогают мне готовиться к урокам и экономить время на поиск нужной информации.',
        author: 'Айжан Бекова',
        status: 'Учитель',
    },
    {
        text: 'С помощью цифровых учебников я быстрее усваиваю материал и могу повторять темы в любое время.',
        author: 'Мадина Ахметова',
        status: 'Ученица',
    },
    {
        text: 'Удобный интерфейс и возможность добавлять заметки делают обучение приятным и продуктивным.',
        author: 'Руслан Капаров',
        status: 'Студент',
    },
    {
        text: 'Эти учебники стали неотъемлемой частью моего образовательного процесса, позволяя учиться где угодно.',
        author: 'Асель Курманова',
        status: 'Учитель',
    },
    {
        text: 'Благодаря электронной версии учебников я всегда имею доступ к нужной информации и могу изучать её в любом месте.',
        author: 'Алина Сарсенова',
        status: 'Ученица',
    },
    {
        text: 'Очень нравится возможность скачивать учебники и работать с ними даже без интернета!',
        author: 'Андрей Миронов',
        status: 'Студент',
    },
    {
        text: 'Современные цифровые учебники позволили улучшить качество преподавания и привлечь внимание студентов.',
        author: 'Марат Жанбаев',
        status: 'Преподаватель',
    },
    {
        text: 'Интерактивные задания помогают мне лучше понимать материал и более эффективно готовиться к экзаменам.',
        author: 'Нуржан Искаков',
        status: 'Учитель',
    },
    {
        text: 'Электронные учебники стали отличным дополнением к традиционным книгам, теперь мои дети учатся эффективнее.',
        author: 'Ермек Кусаинов',
        status: 'Родитель',
    },
    {
        text: 'Качественные учебные материалы и возможность делать пометки помогают мне учиться более эффективно.',
        author: 'Алия Капарова',
        status: 'Ученица',
    },
];

// Custom next arrow component
const CustomNextArrow = ({ onClick }) => (
    <div className="custom-arrow custom-next" onClick={onClick}>
        <RightOutlined />
    </div>
);

// Custom previous arrow component
const CustomPrevArrow = ({ onClick }) => (
    <div className="custom-arrow custom-prev" onClick={onClick}>
        <LeftOutlined />
    </div>
);

const Testimonials = () => (
    <div className="testimonials-container">
        <div className="header-container">
            <div className="blue-gradient-line"></div>
            <h2 className="testimonials-header">Отзывы</h2>
        </div>
        <h3 className="testimonials-subheader">Цифровые учебники - инновационное решение для обучения</h3>
        <Carousel
            autoplay
            dots={false}
            arrows
            nextArrow={<CustomNextArrow />}
            prevArrow={<CustomPrevArrow />}
            slidesToShow={3}
            slidesToScroll={1}
            className="testimonials-carousel"
            responsive={[
                {
                    breakpoint: 1024,
                    settings: {
                        slidesToShow: 2,
                        slidesToScroll: 1,
                    },
                },
                {
                    breakpoint: 600,
                    settings: {
                        slidesToShow: 1,
                        slidesToScroll: 1,
                    },
                },
            ]}
        >
            {testimonials.map((testimonial, index) => (
                <div key={index} className="testimonial-block">
                    <p className="testimonial-text">"{testimonial.text}"</p>
                    <p className="testimonial-author">{testimonial.author}</p>
                    <p className="testimonial-status">{testimonial.status}</p>
                </div>
            ))}
        </Carousel>
    </div>
);

export default Testimonials;
