// modules
import React from 'react';
import { useTranslation } from 'react-i18next'; // Импортируем useTranslation
import './Instructions.css';
import { useColor } from '../Utils/ColorContext';

function Instructions() {
    const { t } = useTranslation(); // Используем хук useTranslation для получения функции t
    const { color } = useColor();

    const titleStyle = {
        color: color === '#3C3C56' ? 'white' : '#7B6CEA',
    };

    return (
        <div className="instructions">
            <h1 style={titleStyle}>{t('Инструкция')}</h1>
            {/* Комментарий: ReactHtmlParser не определен */}
            {/* {ReactHtmlParser(t('landing.manual.content'))} */}
            <p>{t('ВИДЕО')}</p>
        </div>
    );
}

export default Instructions;
