import React from 'react';
import { Carousel } from 'antd';
import './DigitalTextbooks.css';
import book1 from '../images/education/book-1-removebg-preview.png'

const DigitalTextbooks = () => {
    const carouselItems = [
        { id: 1, title: 'Пример книги 1', image: book1 },
        { id: 2, title: 'Пример книги 2', image: book1 },
        { id: 3, title: 'Пример книги 3', image: book1 },
        { id: 4, title: 'Пример книги 4', image: book1 },
    ];

    return (
        <div className="digital-textbooks-container">
            <div className="digital-textbooks-header-container">
                <div className="blue-line-second"></div>
                <h2 className="digital-textbooks-header">
                    Ekitap – современные цифровые учебники
                </h2>
            </div>
            <h3 className="digital-textbooks-subheader">Познакомьтесь с примерами заданий и анимацией</h3>
            <Carousel className="digital-textbooks-carousel" arrows infinite>
                {carouselItems.map((item) => (
                    <div key={item.id} className="carousel-item">
                        <img src={item.image} alt={item.title} className="carousel-item-image" />
                    </div>
                ))}
            </Carousel>
        </div>
    );
};

export default DigitalTextbooks;
