import React, { useState } from "react";
import { useTranslation } from 'react-i18next';

import './WelcomePage.css';
import Modal from './Modal';
import LoginModal from "./LoginModal";
import RegistrationForm from "./RegistrationForm";
import { useColor } from '../Utils/ColorContext';
import mobpk from '../images/landing/mobpk.svg';
import komp from '../images/landing/komp.svg';
import CarouselComponent from './CarouselComponent';
import Features from './Features';
import TeachersFeatures from './TeachersFeatures';
import AboutPlatform from "./AboutPlatform";
import DigitalTextbooks from "./DigitalTextbooks";
import FAQ from "./FAQ";
import Testimonials from "./Testimonials";

    const WelcomePage = () => {
    const { t } = useTranslation();
    const [isHovered, setIsHovered] = useState(false);
    const [isLoginModalOpen, setLoginModalOpen] = useState(false);
    const [isRegistrationModalOpen, setRegistrationModalOpen] = useState(false);
    const [kundelikId, setKundelikId] = useState('');
    const { color } = useColor();

    const headerStyle = {
        backgroundColor: color === '#3C3C56' ? color : 'white',
        color: color === '#3C3C56' ? '#e6f5ff' : 'black',
        transition: 'background-color 1s, color 1s, box-shadow 1s',
    };

    const headerTextStyle = {
        color: color === '#3C3C56' ? 'white' : '#00B9F8',
        transition: 'background-color 1s, color 1s',
    };

    const headerButStyle = {
        backgroundColor: color === '#3C3C56' ? 'white' : '#00B9F8',
        color: color === '#3C3C56' ? '#00B9F8' : 'white',
        transition: 'background-color 1s, color 1s, box-shadow 1s',
    };

    const openRegistrationModal = (e) => {
        e.preventDefault();
        setKundelikId('');
        setRegistrationModalOpen(true);
    };

    const handleMouseEnter = () => {
        setIsHovered(true);
    };

    const handleMouseLeave = () => {
        setIsHovered(false);
    };

    const handleLoginClick = () => {
        setLoginModalOpen(true);
    };

    return (
        <div className="WelcomePage" style={headerStyle}>
            <div className='Info'>
                <div className='Info-left animate__animated animate__slideInLeft'>
                    <div className='Info-text' style={headerTextStyle}>
                        <span>{t("Интерактивная платформа") + " " + t("доступная каждому")}</span>
                    </div>
                    <div className='registration'>
                        <button style={headerButStyle}
                                className={`come ${isHovered ? 'hovered' : ''}`}
                                onMouseEnter={handleMouseEnter}
                                onMouseLeave={handleMouseLeave}
                                onClick={handleLoginClick}>{t("Войти")}</button>
                        <button className='Become-a-member'
                                onClick={openRegistrationModal}>{t("Стать участником")}</button>
                    </div>
                </div>
                <div className='Info-right animate__animated animate__slideInRight'>
                    <div className="Untitled">
                        <img className='fullpkimg' src={komp} alt="Untitled" />
                        <img className='mobpkimg' src={mobpk} alt="mobpk" />
                    </div>
                </div>
            </div>

            {/* Убираем Router и Routes отсюда */}

            {isLoginModalOpen && (
                <Modal isOpen={isLoginModalOpen} onClose={() => setLoginModalOpen(false)}>
                    <LoginModal kundelikId={kundelikId} t={t} />
                </Modal>
            )}

            {isRegistrationModalOpen && (
                <Modal isOpen={isRegistrationModalOpen} onClose={() => setRegistrationModalOpen(false)}>
                    <RegistrationForm kundelikId={kundelikId} />
                </Modal>
            )}

            <CarouselComponent onLoginClick={handleLoginClick} />
            <Features />
            <TeachersFeatures />
            <AboutPlatform onJoinClick={handleLoginClick} />
            <DigitalTextbooks />
            <FAQ />
            <Testimonials />
        </div>
    );
};

export default WelcomePage;
