import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom'; // Импортируем useNavigate в начале файла

// assets
import login_img from "../images/landing/login.svg";
import password_img from "../images/landing/password.svg";

// utils
import './Modal.css';
import './Login.css';
import { useColor } from '../Utils/ColorContext';

const LoginModal = ({
                      forgotPasswordDone,
                      forgotPasswordError,
                      loginDone,
                      loginStatus,
                      makeForgotPassword,
                      makeLogin,
                      role,
                      onClose,
                      t
                    }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isPasswordVisible, setPasswordVisibility] = useState(false);
  const [isForgotPasswordShown, setForgotPasswordVisibility] = useState(false);
  const [loginErrorMsg, setLoginErrorMsg] = useState('');
  const [forgotPasswordMsg, setForgotPasswordMsg] = useState('');

  const navigate = useNavigate(); // Получаем navigate хук

  useEffect(() => {
    if (loginDone && role) {
      const redirectUrl = '/dashboard/courses'; // Default redirect URL
      navigate(redirectUrl); // Используем navigate для перехода
    }
  }, [loginDone, role, navigate]);

  useEffect(() => {
    if (loginStatus) {
      switch (loginStatus) {
        case 401:
          setLoginErrorMsg(t('errors.401'));
          break;
        case 403:
          setLoginErrorMsg(t('errors.403'));
          break;
        case 404:
          setLoginErrorMsg(t('errors.404'));
          break;
        case 503:
          setLoginErrorMsg(t('errors.503'));
          break;
        default:
          setLoginErrorMsg(t('errors.default'));
      }
    }
  }, [loginStatus, t]);

  useEffect(() => {
    if (forgotPasswordDone) {
      setForgotPasswordMsg(<div className="auth-modal-success-msg">{t('landing.forgotmodal.msg.success')}</div>);
    }
  }, [forgotPasswordDone, t]);

  useEffect(() => {
    if (forgotPasswordError) {
      setForgotPasswordMsg(<div className="auth-modal-error-msg">{t('landing.forgotmodal.msg.error')}</div>);
    }
  }, [forgotPasswordError, t]);

  const handleForgot = event => {
    event.preventDefault();
    makeForgotPassword(email).catch(err => console.error(err));
  };

  const handleLoginAs = (role) => {
    let redirectUrl = '/dashboard/courses'; // Default redirect URL

    // Set redirect URL based on role
    switch (role) {
      case 'student':
        redirectUrl = '/student';
        break;
      case 'teacher':
        redirectUrl = '/teacher';
        break;
      case 'expert':
        redirectUrl = '/expert';
        break;
      case 'author':
        redirectUrl = '/author';
        break;
      default:
        redirectUrl = '/';
    }

    navigate(redirectUrl); // Используем navigate для перехода
  };

  const { color } = useColor();
  const headerTextStyle = {
    color: color === '#3C3C56' ? 'white' : 'black',
  };
  const titleStyle = {
    color: color === '#3C3C56' ? 'white' : '#7B6CEA',
  };

  return (
      <>
        {isForgotPasswordShown ? (
            <form className="formlogin" onSubmit={handleForgot}>
              <h1 style={titleStyle}>{t('landing.forgotmodal.header')}</h1>

              <div className="landing-modal-form-note">{t('Введите ваш email в поле и нажмите Отправить.')}</div>
              <div className="landing-modal-form-note">{t('После этого вы получите письмо с дальнейшими указаниями для восстановления вашего пароля.')}</div>

              {forgotPasswordMsg && <div className="landing-modal-message error">{forgotPasswordMsg}</div>}

              <div className='login'>
                <img className='logimg' src={login_img} alt="login"/>
                <label htmlFor="email"></label>
                <input
                    type="text"
                    id="email"
                    name="email"
                    value={email}
                    onChange={event => setEmail(event.target.value)}
                    placeholder='Email'/>
              </div>

              <div className="landing-modal-form-toggle-login" onClick={() => setForgotPasswordVisibility(false)}>
                <span>{t('перейти ко входу')}</span>
              </div>

              <div className='buttonsubmit'>
                <button type="submit">{t('send')}</button>
              </div>
            </form>
        ) : (
            <div className="formlogin">
              <h1 style={titleStyle}>{t('Вход в систему')}</h1>

              {loginErrorMsg && <div className="landing-modal-message error">{loginErrorMsg}</div>}

              <div className='login'>
                <img className='logimg' src={login_img} alt="login"/>
                <label htmlFor="email"></label>
                <input
                    type="text"
                    id="email"
                    name="email"
                    placeholder='Логин'
                    value={email}
                    onChange={event => setEmail(event.target.value)}
                />
              </div>

              <div className='password'>
                <label htmlFor="password"></label>
                <img className='logimg' src={password_img} alt="password"/>
                <input
                    type={isPasswordVisible ? 'text' : 'password'}
                    id="password"
                    name="password"
                    value={password}
                    required
                    placeholder={t('password')}
                    onChange={event => setPassword(event.target.value)}
                />
              </div>

              <div className='helppassword'>
                <div className='Show'>
                  <input
                      type="checkbox"
                      id="showPassword"
                      name="isPasswordVisible"
                      checked={isPasswordVisible}
                      onChange={() => setPasswordVisibility(!isPasswordVisible)}
                  />
                  <label htmlFor="showPassword" style={headerTextStyle}>{t('Показать пароль')}</label>
                </div>
                <div className="forget" onClick={() => setForgotPasswordVisibility(true)} style={headerTextStyle}>{t('забыли пароль?')}</div>
              </div>

              <div className='buttonsubmit'>
                <button type="button" onClick={() => handleLoginAs('student')}>{t('Войти как ученик')}</button>
                <button type="button" onClick={() => handleLoginAs('teacher')}>{t('Войти как учитель')}</button>
                <button type="button" onClick={() => handleLoginAs('expert')}>{t('Войти как эксперт')}</button>
                <button type="button" onClick={() => handleLoginAs('author')}>{t('Войти как автор')}</button>
              </div>

            </div>
        )}
      </>
  );
};

export default LoginModal;
