import React from 'react';
import './Features.css';
import iconConvenient from '../images/education/feature1_2d@2x.png';
import iconEasy from '../images/education/feature2_2d@2x.png';
import iconHandy from '../images/education/feature3_2d@2x.png';
import iconNovelty from '../images/education/feature4_2d@2x.png';
import iconQuality from '../images/education/feature4_2d@2x.png';


const TeachersFeatures = () => {
    return (
        <div className="features-container">
            <h2 className="features-header">Для учителей</h2>
            <p className="features-subheader">Как Ekitpa помогает учителям?</p>
            <div className="features-grid">
                <div className="feature-item">
                    <img src={iconConvenient} alt="Удобно" className="feature-icon"/>
                    <div>
                        <h3 className="feature-title">Удобно</h3>
                        <p className="feature-description">Контроль за учебным процессом в реальном времени</p>
                    </div>
                </div>
                <div className="feature-item">
                    <img src={iconEasy} alt="Легко" className="feature-icon"/>
                    <div>
                        <h3 className="feature-title">Легко</h3>
                        <p className="feature-description">Простое создание электронных журналов</p>
                    </div>
                </div>
                <div className="feature-item">
                    <img src={iconHandy} alt="Все под рукой" className="feature-icon"/>
                    <div>
                        <h3 className="feature-title">Все под рукой</h3>
                        <p className="feature-description">Использование всех составляющих урока</p>
                    </div>
                </div>
                <div className="feature-item">
                    <img src={iconNovelty} alt="Новизна" className="feature-icon"/>
                    <div>
                        <h3 className="feature-title">Новизна</h3>
                        <p className="feature-description">Расширение методов работы учителя</p>
                    </div>
                </div>
                <div className="feature-item">
                    <img src={iconQuality} alt="Качество" className="feature-icon"/>
                    <div>
                        <h3 className="feature-title">Качество</h3>
                        <p className="feature-description">Качественный учебный контент</p>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default TeachersFeatures;
