import React from 'react';
import './Features.css';

import iconConvenient from '../images/education/feature1_2d@2x.png';
import iconEasy from '../images/education/feature2_2d@2x.png';
import iconHandy from '../images/education/feature3_2d@2x.png';
import iconNovelty from '../images/education/feature4_2d@2x.png';
import iconQuality from '../images/education/feature4_2d@2x.png';


const features = [
    {
        icon: iconConvenient,
        title: 'Удобно',
        description: 'Контроль за учебным процессом в реальном времени',
    },
    {
        icon: iconEasy,
        title: 'Легко',
        description: 'Простое создание электронных журналов',
    },
    {
        icon: iconHandy,
        title: 'Все под рукой',
        description: 'Использование всех составляющих урока',
    },
    {
        icon: iconNovelty,
        title: 'Новизна',
        description: 'Расширение методов работы учителя',
    },
    {
        icon: iconQuality,
        title: 'Качество',
        description: 'Качественный учебный контент',
    },
];

const Features = () => {
    return (
        <div className="features-container">
            <h2 className="features-header">Для учеников</h2>
            <p className="features-subheader">Почему с Ekitap интересно учиться?</p>
            <div className="features-grid">
                {features.map((feature, index) => (
                    <div className="feature-item" key={index}>
                        <img src={feature.icon} alt={feature.title} className="feature-icon" />
                        <div>
                            <h3 className="feature-title">{feature.title}</h3>
                            <p className="feature-description">{feature.description}</p>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default Features;
