import React, { useEffect, useRef } from 'react';
import './AboutPlatform.css';
import about from '../images/education/about_2d@2x.png';

const AboutPlatform = ({ onJoinClick }) => {
    const imageRef = useRef(null);

    const animateImage = () => {
        const image = imageRef.current;
        let opacity = 0;
        let scale = 0.8;

        const animate = () => {
            if (opacity < 1) {
                opacity += 0.02;
                scale += 0.01;
                image.style.opacity = opacity;
                image.style.transform = `scale(${scale})`;
                requestAnimationFrame(animate);
            }
        };

        animate();
    };

    useEffect(() => {
        animateImage(); // Изначально запускаем анимацию при загрузке
    }, []);

    return (
        <div className="about-platform-container">
            <div className="about-platform-image">
                <img
                    src={about}
                    alt="Платформа"
                    className="platform-image"
                    ref={imageRef}  // Привязка ссылки к изображению
                    onClick={animateImage} // Анимация запускается при нажатии на изображение
                />
            </div>
            <div className="about-platform-text">
                <h2 className="about-platform-header">
                    <span className="blue-line"></span>О платформе
                </h2>
                <p className="about-platform-description">
                    Web-платформа находится на серверах, размещенных на территории Республики Казахстан.
                    Электронные учебники рекомендованы к использованию в организациях образования Приказами
                    МОН РК № 131, № 216, № 286.
                </p>
                <button className="join-button" onClick={onJoinClick}>
                    Присоединиться
                </button>
            </div>
        </div>
    );
};

export default AboutPlatform;
