// ToggleButton.js
import './ToggleButton.css';
import React, { useState } from 'react';
import { useColor } from '../Utils/ColorContext';
import sunwithe from '../images/landing/sunwithe.svg';
import sunblack from '../images/landing/sunblack.svg';
import moon from '../images/landing/moon.svg';

function ToggleButton() {
    const { color, setColor } = useColor();
    const [toggle, setToggle] = useState(color === '#3C3C56');

    const handleToggle = () => {
        const newColor = !toggle ? '#3C3C56' : '#e6f5ff';
        setToggle(!toggle);
        setColor(newColor);

        // Update CSS variables
        document.documentElement.style.setProperty('--background-color', newColor);
        document.documentElement.style.setProperty(
            '--button-background-color',
            newColor === '#3C3C56' ? '#4CAF50' : '#00b9f8' // Green for dark mode, blue for light mode
        );
        document.documentElement.style.setProperty(
            '--button-text-color',
            newColor === '#3C3C56' ? '#FFFFFF' : '#000000' // White for dark mode, black for light mode
        );
    };

    return (
        <div
            className={`wrg-toggle ${toggle ? 'wrg-toggle--checked' : ''}`}
            onClick={handleToggle}
        >
            <div className="wrg-toggle-container">
                <div className="wrg-toggle-uncheck">
                    <span>
                        <img
                            className="imagesTogg"
                            src={color === '#3C3C56' ? sunblack : sunwithe}
                            alt="Sun Icon"
                        />
                    </span>
                </div>
                <div className="wrg-toggle-check">
                    <span>
                        <img
                            className="imagesTogg"
                            src={moon}
                            alt="Moon Icon"
                        />
                    </span>
                </div>
                <div className="wrg-toggle-circle"></div>
            </div>
        </div>
    );
}

export default ToggleButton;
