import React, { useState } from 'react';
import './RegistrationForm.css';
import { useColor } from '../Utils/ColorContext';

const RegistrationForm = ({ done, error, kundelikId = '', makeRegister, onClose, toggleLoginModalShown, t }) => {
    const [hasAggreed, setAggreed] = useState(false);
    const [showText, setShowText] = useState(true);
    const [showPassword, setShowPassword] = useState(false);

    const [firstName, setFirstName] = useState('');
    const [lastName, setLastName] = useState('');
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');

    const { color } = useColor();

    const handleRegister = event => {
        event.preventDefault();

        setShowText(true);

        makeRegister(firstName, lastName, email, password, kundelikId)
            .then(() => {
                setTimeout(() => {
                    setShowText(false);
                }, 3000);
            })
            .catch(() => {
                setTimeout(() => {
                    setShowText(false);
                }, 3000);
            });
    };

    const headerTextStyle = {
        color: color === '#3C3C56' ? 'white' : 'black',
    };
    const titleStyle = {
        color: color === '#3C3C56' ? 'white' : '#7B6CEA',
    };

    return (
        <div className='formloginreg'>
            <div className='center'>
                <h1 style={titleStyle}>{t && typeof t === 'function' ? t("landing.registermodal.header") : "Register"}</h1>
            </div>
            <form onSubmit={handleRegister}>
                {showText && done && <div className="landing-modal-form-message1 success">{t && typeof t === 'function' ? t('landing.registermodal.msg.success') : "Registration successful!"}</div>}
                {showText && error && <div className="landing-modal-form-message1 error">{t && typeof t === 'function' ? t('landing.registermodal.msg.error') : "An error occurred during registration."}</div>}
                <div className='loginreg'>
                    <label htmlFor="userlastname"></label>
                    <input
                        type="text"
                        id="userlastname"
                        name="userlastname"
                        value={lastName}
                        onChange={event => setLastName(event.target.value)}
                        placeholder={t && typeof t === 'function' ? t('lastName') + '*' : "Фамилия*"}
                        required
                    />
                </div>
                <div className='loginreg'>
                    <label htmlFor="username"></label>
                    <input
                        type="text"
                        id="username"
                        name="username"
                        value={firstName}
                        required
                        placeholder={t && typeof t === 'function' ? t('firstName') + '*' : "Имя*"}
                        onChange={event => setFirstName(event.target.value)}
                    />
                </div>
                <div className='loginreg'>
                    <label htmlFor="Email"></label>
                    <input
                        type="text"
                        id="Email"
                        name="Email"
                        value={email}
                        required
                        placeholder="Email*"
                        onChange={event => setEmail(event.target.value)}
                    />
                </div>
                <div className='loginreg'>
                    <label htmlFor="password"></label>
                    <input
                        id="password"
                        name="password"
                        required
                        type={showPassword ? 'text' : 'password'}
                        placeholder={t && typeof t === 'function' ? t('password') + '*' : "Пароль*"}
                        onChange={event => setPassword(event.target.value)}
                    />
                </div>
                <div className='textreg'>
                    <div className='loginregagreements'>
                        <input
                            type="checkbox"
                            id="showPassword"
                            name="showPassword"
                            checked={showPassword}
                            onChange={() => setShowPassword(!showPassword)} />
                        <label htmlFor="showPassword" style={headerTextStyle}>
                            {t && typeof t === 'function' ? t('landing.registermodal.showpassword') : "Показать пароль"}
                        </label>
                    </div>
                    <div className='helppasswordreg'>
                        <div className='isAgreed'>
                            <input
                                id="isAgreed"
                                name="isAgreed"
                                value={hasAggreed}
                                type="checkbox"
                                onChange={event => setAggreed(event.target.checked)}
                            />
                            <label htmlFor="isAgreed" style={headerTextStyle}>
                                {t && typeof t === 'function' ? t('landing.registermodal.agreement') : "Я принимаю условия пользовательского соглашения и даю согласие на обработку моих персональных данных"}
                            </label>
                        </div>
                    </div>
                    <div className='buttonsubmitreg'>
                        <input disabled={!hasAggreed} type="submit" value={t && typeof t === 'function' ? t('register') : "Зарегестрироваться"} />
                    </div>
                </div>
            </form>
        </div>
    );
}

export default RegistrationForm;

